<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/app/Services/DcpToolRegistry.php';
$registry=new DcpToolRegistry(['version'=>$appConfig['version']],$db,$providers,$devices,$term,$plugins,$crypto);
$definitions=$registry->definitions();$names=array_column($definitions,'name');
ok(count($definitions)===7&&in_array('dcp_create_task',$names,true)&&in_array('dcp_run_safe_terminal',$names,true),'shared MCP tool registry exposes the existing seven-tool catalog');
ok(!array_key_exists('policy',$definitions[0]),'internal DCP policy metadata is not leaked into the public MCP tool schema');
$taskPolicy=$registry->policy('dcp_create_task');$mailPolicy=$registry->policy('dcp_read_unread_mail');$safePolicy=$registry->policy('dcp_run_safe_terminal');
ok(($taskPolicy['classification']??'')==='state-change'&&($taskPolicy['approval_required']??false)===true,'task creation is explicitly classified as an approval-required state change');
ok(($mailPolicy['classification']??'')==='sensitive-read'&&($mailPolicy['approval_required']??false)===true,'mail access is explicitly classified as an approval-required sensitive read');
ok(($safePolicy['classification']??'')==='safe-read'&&($safePolicy['approval_required']??true)===false,'safe terminal capability is classified as read-only and still allow-listed');
$unknownRejected=false;try{$registry->call('dcp_unknown_tool',[]);}catch(InvalidArgumentException $e){$unknownRejected=true;}ok($unknownRejected,'shared registry rejects unknown tool names');
$badArgumentsRejected=false;try{$registry->call('dcp_create_task',['title'=>'x','description'=>'y','actions'=>[['type'=>'write_file','path'=>'x']],'unexpected'=>true]);}catch(InvalidArgumentException $e){$badArgumentsRejected=true;}ok($badArgumentsRejected,'shared registry rejects arguments outside the published JSON schema');
$badActionRejected=false;try{$registry->call('dcp_create_task',['title'=>'x','description'=>'y','actions'=>[['type'=>'write_file','path'=>'x']]]);}catch(InvalidArgumentException $e){$badActionRejected=true;}ok($badActionRejected,'shared registry rejects write actions without required file content');
$blankTaskRejected=false;try{$registry->call('dcp_create_task',['title'=>'  ','description'=>'Valid description','actions'=>[['type'=>'create_directory','path'=>'safe']]]);}catch(InvalidArgumentException $e){$blankTaskRejected=true;}ok($blankTaskRejected,'shared registry rejects blank task titles before persistence');$badDeviceRejected=false;try{$registry->call('dcp_create_task',['title'=>'Bad device','description'=>'Reject invalid device ID','target_device_id'=>'../other','actions'=>[['type'=>'create_directory','path'=>'safe']]]);}catch(InvalidArgumentException $e){$badDeviceRejected=true;}ok($badDeviceRejected,'shared registry rejects malformed target device identifiers');$traversalTaskRejected=false;try{$registry->call('dcp_create_task',['title'=>'Traversal','description'=>'Reject unsafe workspace path','actions'=>[['type'=>'create_directory','path'=>'../outside']]]);}catch(InvalidArgumentException $e){$traversalTaskRejected=true;}ok($traversalTaskRejected,'shared registry rejects absolute and traversal paths before creating tasks');$oversizedContentRejected=false;try{$registry->call('dcp_create_task',['title'=>'Oversized','description'=>'Reject oversized bytes','actions'=>[['type'=>'write_file','path'=>'large.bin','content'=>str_repeat('x',1048577)]]]);}catch(InvalidArgumentException $e){$oversizedContentRejected=true;}ok($oversizedContentRejected,'shared registry enforces the one-megabyte byte limit before creating tasks');
$mcpConsentDenied=false;try{$registry->call('dcp_run_safe_terminal',['command'=>'pwd'],['caller'=>'mcp']);}catch(RuntimeException $e){$mcpConsentDenied=str_contains($e->getMessage(),'integration');}ok($mcpConsentDenied,'MCP dispatch requires an explicitly configured local integration context');
$agentDenied=false;try{$registry->call('dcp_run_safe_terminal',['command'=>'pwd'],['caller'=>'agent','capabilities'=>[]]);}catch(RuntimeException $e){$agentDenied=true;}ok($agentDenied,'agent tool calls are denied unless the matching DCP capability is explicitly enabled');
$safeResult=$registry->call('dcp_run_safe_terminal',['command'=>'pwd'],['caller'=>'agent','capabilities'=>['terminal.safe-read']]);ok(($safeResult['exit_code']??1)===0,'agent can use an explicitly enabled safe-read tool');
$sensitiveDenied=false;try{$registry->call('dcp_list_providers',[],['caller'=>'agent','capabilities'=>['provider.list']]);}catch(RuntimeException $e){$sensitiveDenied=str_contains($e->getMessage(),'approval');}ok($sensitiveDenied,'sensitive reads remain blocked until an explicit plan-bound approval exists');
$staleApprovalDenied=false;$providerArgs=[];$providerHash=$registry->argumentsHash($providerArgs);try{$registry->call('dcp_list_providers',$providerArgs,['caller'=>'agent','capabilities'=>['provider.list'],'approval_status'=>'approved','plan_version'=>2,'approval_plan_version'=>1,'approved_arguments_hash'=>$providerHash]);}catch(RuntimeException $e){$staleApprovalDenied=true;}ok($staleApprovalDenied,'approval from an older plan version cannot authorize a tool call');
$approvedProviders=$registry->call('dcp_list_providers',$providerArgs,['caller'=>'agent','capabilities'=>['provider.list'],'approval_status'=>'approved','plan_version'=>2,'approval_plan_version'=>2,'approved_arguments_hash'=>$providerHash]);ok(isset($approvedProviders['providers'])&&is_array($approvedProviders['providers']),'sensitive read runs only after exact arguments and current plan version are approved');
$taskArgs=['title'=>'Registry approval contract','description'=>'Must remain approval required','actions'=>[['type'=>'create_directory','path'=>'registry-approval-contract']]];$taskHash=$registry->argumentsHash($taskArgs);$taskDenied=false;try{$registry->call('dcp_create_task',$taskArgs,['caller'=>'agent','capabilities'=>['task.create'],'plan_version'=>3]);}catch(RuntimeException $e){$taskDenied=str_contains($e->getMessage(),'approval');}ok($taskDenied,'state-changing task creation is blocked without an explicit approval');
$taskCreated=$registry->call('dcp_create_task',$taskArgs,['caller'=>'agent','capabilities'=>['task.create'],'approval_status'=>'approved','plan_version'=>3,'approval_plan_version'=>3,'approved_arguments_hash'=>$taskHash]);$createdStatus=$db->prepare('SELECT status FROM tasks WHERE id=?');$createdStatus->execute([$taskCreated['id']]);ok(($taskCreated['status']??'')==='approval_required'&&$createdStatus->fetchColumn()==='approval_required','approved task creation still creates an approval-required task and never executes it');$db->prepare('DELETE FROM tasks WHERE id=?')->execute([$taskCreated['id']]);
